INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "created_at", "resolved", "resolved_at", "resolution_notes") VALUES ('c6dd3f06-9585-4710-8c64-89745334d926', '7bryz6h8llwy6by3xsvxnj', 'el agente no entiende o no puede hacer lo que el estoy pidiendo.', '["Musly Router","Agente de Agendamiento (03-melosmile-agent-appointment)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-07-24T00:39:20.158Z"},{"role":"user","text":"cual es la agenda de la semana?","timestamp":"2026-07-24T00:39:33.774Z"},{"role":"assistant","text":"Aquí tienes la agenda para esta semana:\n\n**Jueves, 23 de julio de 2026:**\n* **16:30:** Paciente General en Clinica Daniel Bustamante con Dr. Shirley García. Motivo: Nueva cita (IA). Estado: Confirmada.\n* **16:45:** Paciente General en Clinica Daniel Bustamante con Dr. Shirley García. Motivo: Nueva cita (IA). Estado: Confirmada.\n\n**Viernes, 24 de julio de 2026:**\n* **15:00:** Test General en Clínica Goya con Dr. Osly Melo. Motivo: Retenedor Fijo. Estado: Pendiente.\n* **16:30:** Munir Manuel Callaos Cardama en Clínica Goya con Dr. Osly Melo. Motivo: Consulta. Estado: Confirmada.","intent":"schedule_appointment","timestamp":"2026-07-24T00:39:38.716Z"},{"role":"user","text":"elimina las citas del jueves 23","timestamp":"2026-07-24T00:40:01.573Z"},{"role":"assistant","text":"No puedo eliminar citas por fecha. Necesito el nombre del paciente o el ID de la cita. Por favor, indícame el nombre del paciente o el ID de la cita para poder ayudarte.","intent":"schedule_appointment","timestamp":"2026-07-24T00:40:04.856Z"},{"role":"user","text":"las de paciente general","timestamp":"2026-07-24T00:40:40.759Z"},{"role":"assistant","text":"Para esta semana, hay 4 citas:\n1. El 23 de julio a las 16:30, Paciente General tiene una cita de Nueva cita (IA) en Clinica Daniel Bustamante con la Dra. Shirley García. Esta cita está confirmada.\n2. El 23 de julio a las 16:45, Paciente General tiene una cita de Nueva cita (IA) en Clinica Daniel Bustamante con la Dra. Shirley García. Esta cita está confirmada.\n3. El 24 de julio a las 15:00, Test General tiene una cita de Retenedor Fijo en Clínica Goya con el Dr. Osly Melo. Esta cita está pendiente.\n4. El 24 de julio a las 16:30, Munir Manuel Callaos Cardama tiene una cita de Consulta en Clínica Goya con el Dr. Osly Melo. Esta cita está confirmada.","intent":"schedule_appointment","timestamp":"2026-07-24T00:40:45.551Z"},{"role":"user","text":"elimina las de Paciente General del jueves 23","timestamp":"2026-07-24T00:41:21.894Z"},{"role":"assistant","text":"Lo siento, ha habido un problema al buscar al paciente. Por favor, inténtalo de nuevo más tarde.","intent":"schedule_appointment","timestamp":"2026-07-24T00:41:37.184Z"}]', '2026-07-24T00:41:56.947+00:00', true, '2026-07-24T00:44:42.409+00:00', 'Creado Tool_Update_Appointment en n8n y actualizado /api/appointments/update para soportar cancelación/modificación múltiple por nombre de paciente y fecha en lenguaje natural. Mapeados estados enum a español (Cancelada).') ON CONFLICT DO NOTHING;
INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "created_at", "resolved", "resolved_at", "resolution_notes") VALUES ('502a1ba5-6b91-4aa1-b6c3-59f2413505b6', 'aouo0ovlsvf4n1ituijik', 'No reconocio al paciente al quele estaba pidiendo que ejecutara una accion', '["Musly Router","Agente de Agendamiento (03-melosmile-agent-appointment)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-07-24T00:55:59.970Z"},{"role":"user","text":"agenda de la semana","timestamp":"2026-07-24T00:56:06.448Z"},{"role":"assistant","text":"Aquí tienes la agenda para esta semana (del 20 de julio al 26 de julio de 2026):\n\n1.  **24 de julio a las 15:00**: Paciente Test General, motivo Retenedor Fijo, en la Clínica Goya, con el Dr. Osly Melo. El estado es Pendiente.\n2.  **24 de julio a las 16:30**: Paciente Munir Manuel Callaos Cardama, motivo Consulta, en la Clínica Goya, con el Dr. Osly Melo. El estado es Confirmada.","intent":"schedule_appointment","timestamp":"2026-07-24T00:56:11.018Z"},{"role":"user","text":"cambia la de Test General para el sabado a la misma hora","timestamp":"2026-07-24T00:56:41.988Z"},{"role":"assistant","text":"Lo siento, ha habido un error al buscar el paciente \"Test General\". ¿Podrías confirmarme el nombre completo del paciente o si es un nuevo paciente?","intent":"schedule_appointment","timestamp":"2026-07-24T00:56:45.886Z"}]', '2026-07-24T00:57:53.462+00:00', true, '2026-07-24T00:58:32.317+00:00', 'Implementado algoritmo de puntuación por relevancia (exactness scoring) en /api/patients/search y /api/appointments/update. Test General ya se distingue al 100% de Paciente General. Además se añadió soporte para días relacionales en español (sábado, domingo).') ON CONFLICT DO NOTHING;
INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "created_at", "resolved", "resolved_at", "resolution_notes") VALUES ('2dd5e9ea-a052-4698-b11e-1fbde4b3930b', 'nyptzweoffakq921qf7md', 'Le ha costado seguir las instrucciones que se le pide', '["Musly Router","Agente General / QA (01-melosmile-agent-qa)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-07-24T01:00:04.865Z"},{"role":"user","text":"agenda de la semana","timestamp":"2026-07-24T01:00:11.270Z"},{"role":"assistant","text":"Aquí tienes la agenda para esta semana (2026-07-20 al 2026-07-26):\n\n*   **24 de julio de 2026 a las 16:30**: Cita de Munir Manuel Callaos Cardama para una Consulta en la Clínica Goya. Estado: Confirmada.\n*   **25 de julio de 2026 a las 15:00**: Cita de Test General para un Retenedor Fijo en la Clínica Goya. Estado: Pendiente.","intent":"schedule_appointment","timestamp":"2026-07-24T01:00:18.822Z"},{"role":"user","text":"cambia la de Test General a las 12:00","timestamp":"2026-07-24T01:00:48.181Z"},{"role":"assistant","text":"Para poder cambiar la cita, necesito saber la fecha de la cita y el nombre completo del paciente. ¿Me puedes proporcionar esa información, por favor?","intent":"schedule_appointment","timestamp":"2026-07-24T01:00:51.049Z"},{"role":"user","text":"Test General a las 12:00 del sabado","timestamp":"2026-07-24T01:01:11.448Z"},{"role":"assistant","text":"Necesito que me especifiques el día y el mes del sábado para poder agendar la cita.","intent":"schedule_appointment","timestamp":"2026-07-24T01:01:14.149Z"},{"role":"user","text":"el mismo dia a las 12:00","timestamp":"2026-07-24T01:01:38.548Z"},{"role":"assistant","text":"Necesito el nombre del paciente para poder agendar la cita.","intent":"schedule_appointment","timestamp":"2026-07-24T01:01:40.714Z"},{"role":"user","text":"Test General","timestamp":"2026-07-24T01:01:46.787Z"},{"role":"assistant","text":"No he reconocido bien la petición. Por favor, especifica más detalladamente tu solicitud. ¿Te refieres a alguna de las siguientes opciones: agendar cita, consultar información del paciente, consultar facturación o registrar una nota clínica?","intent":"general_query","timestamp":"2026-07-24T01:01:48.294Z"}]', '2026-07-24T01:02:10.273+00:00', true, '2026-07-24T01:12:58.381+00:00', 'Añadida regla en Agent_Scheduling para ejecutar inmediatamente Tool_Update_Appointment sin pedir aclaración al recibir órdenes de modificar/mover hora/fecha de una cita recíentemente mencionada o en contexto.') ON CONFLICT DO NOTHING;